+
+export interface FallbackCardView extends MarginCardView {
+  /** Pinned cards, unsent drafts and in-flight replies survive scrolling away. */
+  keepOpen: boolean;
+  /** The manuscript scroller's visible vertical interval, clipped to the window. */
+  viewport?: { top: number; bottom: number };
+}
+
+/** Follow a fallback passage, closing idle cards or keeping protected ones on screen. */
+export function computeFallbackCardGeometry(view: FallbackCardView): PopoverGeometry | null {
+  const margin = POPOVER_CARD_MARGIN;
+  const viewportTop = Math.max(0, view.viewport?.top ?? 0);
+  const viewportBottom = Math.min(view.vh, view.viewport?.bottom ?? view.vh);
+  const outside = view.rect.bottom <= viewportTop || view.rect.top >= viewportBottom;
+  if (outside && !view.keepOpen) return null;
+  const clamp = (value: number, low: number, high: number) =>
+    Math.max(low, Math.min(value, Math.max(low, high)));
+  const edge = view.rect.bottom <= viewportTop
+    ? viewportTop + margin : viewportBottom - margin;
+  const geometry = computeMarginCardGeometry({
+    ...view,
+    rect: outside ? { left: view.rect.left, top: edge, bottom: edge } : view.rect,
+  });
+  const maxH = Math.min(geometry.maxH, Math.max(0, viewportBottom - viewportTop - margin * 2));
+  return {
+    ...geometry,
+    maxH,
+    top: geometry.top === null ? null
+      : clamp(geometry.top, viewportTop + margin, viewportBottom - maxH - margin),
+    bottom: geometry.bottom === null ? null
+      : clamp(geometry.bottom, view.vh - viewportBottom + margin, view.vh - viewportTop - maxH - margin),
+  };
+}
